-- Operator-only rollback fixture. Existing account/session binding is not JWT/browser proof.
begin;
set local lock_timeout='5s';
set local statement_timeout='45s';
select pg_advisory_xact_lock(hashtextextended('e7ca010b-de06-4e0e-856d-f4ad54d5fcaa',0));
do $$ declare sid uuid;begin
 if exists(select 1 from rhh.professionals where owner_id='e7ca010b-de06-4e0e-856d-f4ad54d5fcaa') then raise exception 'Existing listing; preserve and stop';end if;
 if not exists(select 1 from rhh.accounts a join auth.users u on u.id=a.user_id where a.user_id='e7ca010b-de06-4e0e-856d-f4ad54d5fcaa' and a.role='member' and u.email_confirmed_at is not null) then raise exception 'Designated confirmed member unavailable';end if;
 select id into sid from auth.sessions where user_id='e7ca010b-de06-4e0e-856d-f4ad54d5fcaa' and (not_after is null or not_after>clock_timestamp()) limit 1;
 if sid is null then raise exception 'Existing designated session unavailable';end if;
 perform set_config('request.jwt.claim.sub','e7ca010b-de06-4e0e-856d-f4ad54d5fcaa',true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub','e7ca010b-de06-4e0e-856d-f4ad54d5fcaa','session_id',sid)::text,true);
end $$;
create temp table credential_results(test text primary key,passed boolean not null check(passed));
grant insert on pg_temp.credential_results to authenticated,anon;
insert into rhh.professionals(id,owner_id,business_name,city,state,description,healthy_home_practices) values('30000000-0000-4000-8000-0000000000c3','e7ca010b-de06-4e0e-856d-f4ad54d5fcaa','CREDENTIAL TEST - ROLLBACK ONLY','Raleigh','NC','Rollback-only credential fixture, never committed.','Rollback-only practices.');
insert into rhh.applications(professional_id,contact_name,contact_email) values('30000000-0000-4000-8000-0000000000c3','Test fixture','fixture@example.invalid');
insert into rhh.memberships(professional_id) values('30000000-0000-4000-8000-0000000000c3');
insert into rhh.credentials(id,professional_id,name) values('30000000-0000-4000-8000-0000000000c4','30000000-0000-4000-8000-0000000000c3','Submitted rollback-only test claim');
set local role authenticated;
do $$ declare result jsonb;draft jsonb;denied boolean;begin
 result:=public.rhh_member_credentials();
 insert into pg_temp.credential_results values('saved_claim_starts_unverified',result->'claims'->0->>'state'='pending' and result->'claims'->0->>'verification'='unverified');
 insert into pg_temp.credential_results values('member_projection_excludes_review_metadata',not((result->'claims'->0)?|array['reviewedBy','reviewedAt','reason','ownerId','objectPath']));
 draft:=public.rhh_member_credentials('{"action":"reserve","claimId":"30000000-0000-4000-8000-0000000000c4"}');
 insert into pg_temp.credential_results values('owner_listing_bound_randomized_path',draft->>'objectPath'='e7ca010b-de06-4e0e-856d-f4ad54d5fcaa/30000000-0000-4000-8000-0000000000c3/'||(draft->>'id')||'.webp');
 insert into pg_temp.credential_results values('selection_does_not_associate',public.rhh_member_credentials()->'claims'->0->>'evidenceId' is null);
 insert into pg_temp.credential_results values('own_draft_route',public.rhh_credential_file((draft->>'id')::uuid)->>'id'=draft->>'id');
 denied:=false;begin perform public.rhh_member_credentials(jsonb_build_object('action','attach','claimId','30000000-0000-4000-8000-0000000000c4','target',draft->>'id','version',1));exception when sqlstate 'PT409' then denied:=true;end;
 insert into pg_temp.credential_results values('incomplete_upload_cannot_replace',denied);
 denied:=false;begin perform public.rhh_member_credentials('{"action":"attach","claimId":"30000000-0000-4000-8000-0000000000c4","target":null,"version":1,"verification":"verified"}');exception when sqlstate '22023' then denied:=true;end;
 insert into pg_temp.credential_results values('forged_verification_denied',denied);
 denied:=false;begin perform public.rhh_admin_credentials();exception when insufficient_privilege then denied:=true;end;
 insert into pg_temp.credential_results values('member_admin_read_denied',denied);
 denied:=false;begin perform public.rhh_review_credential('{"claimId":"30000000-0000-4000-8000-0000000000c4","evidenceId":null,"version":1,"action":"verify","reason":"Forged member review"}');exception when insufficient_privilege then denied:=true;end;
 insert into pg_temp.credential_results values('member_admin_action_denied',denied);
 denied:=false;begin perform public.rhh_credential_file((draft->>'id')::uuid,true);exception when insufficient_privilege then denied:=true;end;
 insert into pg_temp.credential_results values('admin_mode_spoof_denied',denied);
 denied:=false;begin update rhh.credentials set verification='verified';exception when insufficient_privilege then denied:=true;end;
 insert into pg_temp.credential_results values('direct_self_verification_denied',denied);
 denied:=false;begin perform 1 from rhh_private.credential_evidence;exception when insufficient_privilege then denied:=true;end;
 insert into pg_temp.credential_results values('raw_evidence_metadata_denied',denied);
 denied:=false;begin perform 1 from rhh_private.credential_reviews;exception when insufficient_privilege then denied:=true;end;
 insert into pg_temp.credential_results values('raw_review_history_denied',denied);
 insert into pg_temp.credential_results values('guessed_evidence_unavailable',public.rhh_credential_file('00000000-0000-4000-8000-000000000001') is null);
 perform public.rhh_member_credentials(jsonb_build_object('action','cancel','target',draft->>'id'));
 insert into pg_temp.credential_results values('canceled_draft_not_routable',public.rhh_credential_file((draft->>'id')::uuid) is null);
 insert into pg_temp.credential_results values('cleanup_grace_protects_inflight_upload',public.rhh_member_credentials('{"action":"cleanup"}')='[]'::jsonb);
end $$;
reset role;
set local role anon;
do $$ declare denied boolean;begin
 denied:=false;begin perform public.rhh_member_credentials();exception when insufficient_privilege then denied:=true;end;
 insert into pg_temp.credential_results values('anonymous_member_credentials_denied',denied);
 denied:=false;begin perform public.rhh_admin_credentials();exception when insufficient_privilege then denied:=true;end;
 insert into pg_temp.credential_results values('anonymous_admin_credentials_denied',denied);
 denied:=false;begin perform public.rhh_credential_file('00000000-0000-4000-8000-000000000001');exception when insufficient_privilege then denied:=true;end;
 insert into pg_temp.credential_results values('anonymous_evidence_denied',denied);
end $$;
reset role;
select test,passed from credential_results order by test;
rollback;
